  signal:'<path d="M5 9a10 10 0 0 1 14 0M8 12a6 6 0 0 1 8 0M11 15a2 2 0 0 1 2 0"/><circle cx="12" cy="18" r="1"/>',
  cache:'<path d="M4 8h16v11H4zM3 8l2-4h14l2 4M12 8v11"/><path d="M9 12h6"/>',
  echo:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2M3 12h3M18 12h3"/>',
  trace:'<path d="M12 3 8 10l4 11 4-11Z"/><path d="m5 8 3 2m11-2-3 2M5 16l4-2m10 2-4-2"/>',
  event:'<path d="m12 3 2.2 6.8H21l-5.5 4 2.1 6.7-5.6-4.1-5.6 4.1 2.1-6.7-5.5-4h6.8Z"/>',
  user:'<circle cx="12" cy="8" r="3"/><path d="M5.5 20c.8-4 3-6 6.5-6s5.7 2 6.5 6"/>',
